SELECT 
  FROM SM_STORED_FILE


        AND STORAGE_SERVER_ID = #{storageServerId}


        AND STATUS = #{status}


        AND (LOWER(ORIGINAL_NAME) LIKE #{keyword}
          OR LOWER(TITLE) LIKE #{keyword}
          OR LOWER(TAGS) LIKE #{keyword}
          OR LOWER(DESCRIPTION) LIKE #{keyword})


 ORDER BY UPLOADED_AT DESC
